import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String[] limits = sc.nextLine().trim().split("\\s+");
        long maxStartup = Long.parseLong(limits[0]);
        long maxMemory = Long.parseLong(limits[1]);
        String required = limits[2];

        int n = Integer.parseInt(sc.nextLine().trim());
        String best = null;
        long bestStartup = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            String[] row = sc.nextLine().trim().split("\\s+");
            String name = row[0];
            long startup = Long.parseLong(row[1]);
            long memory = Long.parseLong(row[2]);
            Set<String> standards = new HashSet<>(Arrays.asList(row[3].split(",")));

            String failed = null;
            if (startup > maxStartup) failed = "startup";
            else if (memory > maxMemory) failed = "memory";
            else if (!required.equals("none") && !standards.contains(required)) failed = "standard";

            if (failed == null) {
                System.out.println(name + " OK");
                if (startup < bestStartup) {          // 同じなら先に読んだものを残す
                    bestStartup = startup;
                    best = name;
                }
            } else {
                System.out.println(name + " NG " + failed);
            }
        }
        System.out.println(best == null ? "NONE" : "CANDIDATE " + best);
    }
}

