public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int ws = sc.nextInt(), wo = sc.nextInt(), wp = sc.nextInt(), minEach = sc.nextInt(), n = sc.nextInt();
        String best = "NONE";
        int top = - 1;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int standards = sc.nextInt(), operations = sc.nextInt(), performance = sc.nextInt();
            if (standards < minEach || operations < minEach || performance < minEach) {
                System.out.println(name + " DISQUALIFIED");
                continue;
            }
            int total = standards * ws + operations * wo + performance * wp;
            System.out.println(name + " " + total);
            if (total > top) {
                top = total;
                best = name;
            }
        }
        System.out.println(top < 0 ? "PICK NONE" : "PICK " + best + " " + top);
    }
}

