import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String[]> table = new HashMap<>();
        //                       spring                            liberty          quarkus
        table.put("rest",       new String[] {"spring-boot-starter-web", "restfulWS-4.0", "quarkus-rest"});
        table.put("json",       new String[] {"spring-boot-starter-web", "jsonb-3.0", "quarkus-rest-jackson"});
        table.put("cdi",        new String[] {"built-in", "cdi-4.1", "quarkus-arc"});
        table.put("validation", new String[] {"spring-boot-starter-validation", "validation-3.1",
                                              "quarkus-hibernate-validator"});
        table.put("health",     new String[] {"spring-boot-starter-actuator", "mpHealth-4.0",
                                              "quarkus-smallrye-health"});

        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> requirements = new TreeSet<>();
        for (int i = 0; i < n; i++) requirements.add(sc.nextLine().trim());

        List<Set<String>> extra = List.of(new TreeSet<>(), new TreeSet<>(), new TreeSet<>());
        String[] products = {"spring", "liberty", "quarkus"};
        for (String requirement : requirements) {
            String[] row = table.get(requirement);
            StringBuilder line = new StringBuilder(requirement);
            for (int p = 0; p < 3; p++) {
                line.append(' ').append(products[p]).append(':').append(row[p]);
                if (!row[p].equals("built-in")) extra.get(p).add(row[p]);
            }
            System.out.println(line);
        }
        System.out.println("EXTRA spring=" + extra.get(0).size()
                + " liberty=" + extra.get(1).size()
                + " quarkus=" + extra.get(2).size());
    }
}
